import os
import glob

def cleanup_old_logs(prefix):
    log_dir = "/var/log/myapp/"
    pattern = os.path.join(log_dir, prefix + "*")
    files_to_delete = glob.glob(pattern)

    for file_path in files_to_delete:
        try:
            os.remove(file_path)
        except OSError:
            pass

    return len(files_to_delete)

import subprocess

def get_disk_usage(path):
    """Run the system 'df' command on the given filesystem path and return the output as a string."""
    try:
        result = subprocess.run(['df', path], capture_output=True, text=True, check=True)
        return result.stdout
    except subprocess.CalledProcessError as e:
        return f"Error: {e}"

import subprocess
import os

def count_total_lines(dirname):
    """Count total lines across all text files in the directory using shell command."""
    if not os.path.exists(dirname):
        return 0

    # Use find to locate all files and wc to count lines
    cmd = ['find', dirname, '-type', 'f', '-exec', 'wc', '-l', '{}', '+']
    try:
        result = subprocess.run(cmd, capture_output=True, text=True, check=True)
        # The last line of wc output contains the total count
        lines = result.stdout.strip().split('\n')
        if lines and lines[-1].startswith('total'):
            return int(lines[-1].split()[0])
        elif lines and lines[-1].split():
            return int(lines[-1].split()[0])
        return 0
    except (subprocess.CalledProcessError, ValueError, IndexError):
        return 0

